def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_me, last_opp = history[-1]

    opp_def_streak = 0
    for me, opp in reversed(history):
        if opp == 'D':
            opp_def_streak += 1
        else:
            break

    my_def_streak = 0
    for me, opp in reversed(history):
        if me == 'D':
            my_def_streak += 1
        else:
            break

    opp_defects_total = 0
    for me, opp in history:
        if opp == 'D':
            opp_defects_total += 1

    if opp_def_streak >= 8:
        return 'D'

    if last_opp == 'C':
        if my_def_streak > 0:
            return 'D'
        if opp_defects_total == 0 and n >= 20:
            if rng.random() < 0.1:
                return 'D'
        return 'C'

    if opp_def_streak == 1:
        return 'C'

    if my_def_streak >= 3 and opp_def_streak >= 3:
        return 'C'

    return 'D'
